-- Rows every Castaway database starts with: the internal background-tasks user (id 1) with its
-- API key, settings and default collection, the default app, email and AI settings, and the
-- system playlists. The __CASTAWAY_*__ values are generated for each install when this runs.

SELECT pg_catalog.setval('public."APIKeys_apikeyid_seq"', 1, true);
SELECT pg_catalog.setval('public."AppSettings_appsettingsid_seq"', 1, true);
SELECT pg_catalog.setval('public."Collections_collectionid_seq"', 1, true);
SELECT pg_catalog.setval('public."EmailSettings_emailsettingsid_seq"', 1, true);
SELECT pg_catalog.setval('public."Playlists_playlistid_seq"', 7, true);
SELECT pg_catalog.setval('public."UserSettings_usersettingid_seq"', 1, true);
SELECT pg_catalog.setval('public."UserStats_userstatsid_seq"', 1, true);
SELECT pg_catalog.setval('public."Users_userid_seq"', 1, true);
